-- 知识点 227 节内容清洗（2026-10-28，AI 辅助 + 人工校验）
-- 目的：修正标题/段落/OCR/LaTeX；保留全部知识点 ID。
-- 备份表：t_knowledge_point_backup_20261028_227
-- 回滚：按 id 从备份表恢复 title/content/section。
begin;
create table if not exists t_knowledge_point_backup_20261028_227 as
select * from t_knowledge_point where id in (24394,26404,26468,26619,26620,26621,26622,26623,26624,26625,26626,26627,26900,27120);

update t_knowledge_point set title = $kp$人工智能加速与其他学科领域交叉渗透$kp$, content = $kp$人工智能本身是一门综合性的前沿学科和高度交叉的复合型学科，研究范畴广泛而又异常复杂，其发展需要与计算机科学、数学、认知科学、神经科学和社会科学等学科深度融合。$kp$, section = '' where id = 24394;
update t_knowledge_point set title = $kp$物联网与人工智能的结合$kp$, content = $kp$人工智能再次成为物联网的重要参与者。充分利用数据，需要人工智能提供计算帮助。人工智能是理解所收集的大量数据并提高其业务价值所必需的基本要素。人工智能将在以下领域帮助物联网数据分析：数据准备、数据发现、流数据的可视化、数据的时间序列准确性、预测和高级分析，以及实时地理空间和位置（后勤）数据。包括亚马逊、微软和谷歌在内的主要云供应商越来越多地希望基于其AI功能展开竞争。各种初创企业希望通过能够利用机器学习和深度学习的AI算法，使企业能够从不断增长的数据量中提取更多价值。$kp$, section = '' where id = 26404;
update t_knowledge_point set title = $kp$人工智能技术与产业结合推动爆发式增长$kp$, content = $kp$越来越多的物品成为移动互联网连接对象，智能可穿戴设备、智能家居、智能机器人等会更加广泛地进入大众生活，同时智能硬件也将与医疗、交通、能源、教育等传统行业深度融合。

随着我国人工智能产业的不断发展与完善，在国家新一代信息产业、“互联网+”、人工智能相关规划和行动计划的支持下，我国形成了较为完整的产业链条。从产业链层面看，我国在基础层、技术平台层和应用层都完成了相应的布局。一方面，移动互联、物联网、信息共享等带来了数据量的爆发；另一方面，国内云计算、超算等计算能力明显提升，国产芯片和模块也有所提高，对人工智能算法和技术的支撑能力正在加强。在语音技术、计算机视觉等未来几年内有望落地或者量产的技术中，我国均已经在加紧部署。$kp$, section = '' where id = 26468;
update t_knowledge_point set title = $kp$人工智能未来发展趋势概述$kp$, content = $kp$经过60多年的发展，人工智能在算法、算力（计算能力）和算料（数据）“三算”方面取得了重要突破，正处于从“不能用”到“可以用”的技术拐点，但是距离“很好用”还有诸多瓶颈。那么在可以预见的未来，人工智能发展将会出现怎样的趋势与特征呢？$kp$, section = '' where id = 26619;
update t_knowledge_point set title = $kp$从专用智能向通用智能发展$kp$, content = $kp$如何实现从专用人工智能向通用人工智能的跨越式发展，既是下一代人工智能发展的必然趋势，也是研究与应用领域的重大挑战。2016年10月，美国国家科学技术委员会发布《国家人工智能研究与发展战略计划》，提出在美国的人工智能长期发展策略中要着重研究通用人工智能。阿尔法狗系统开发团队创始人戴密斯·哈萨比斯提出朝着“创造解决世界上一切问题的通用人工智能”这一目标前进。微软在2017年成立了通用人工智能实验室，众多感知、学习、推理、自然语言理解等方面的科学家参与其中。$kp$, section = '' where id = 26620;
update t_knowledge_point set title = $kp$从人工智能向人机混合智能发展$kp$, content = $kp$借鉴脑科学和认知科学的研究成果是人工智能的一个重要研究方向。人机混合智能旨在将人的作用或认知模型引入人工智能系统中，提升人工智能系统的性能，使人工智能成为人类智能的自然延伸和拓展，通过人机协同更加高效地解决复杂问题。在我国新一代人工智能规划和美国脑计划中，人机混合智能都是重要的研发方向。$kp$, section = '' where id = 26621;
update t_knowledge_point set title = $kp$从“人工+智能”向自主智能系统发展$kp$, content = $kp$当前人工智能领域的大量研究集中在深度学习，但是深度学习的局限是需要大量人工干预，比如人工设计深度神经网络模型、人工设定应用场景、人工采集和标注大量训练数据、用户需要人工适配智能系统等，非常费时费力。因此，科研人员开始关注减少人工干预的自主智能方法，提高机器智能对环境的自主学习能力。例如阿尔法狗系统的后续版本阿尔法元从零开始，通过自我对弈强化学习实现围棋、国际象棋、日本将棋的“通用棋类人工智能”。在人工智能系统的自动化设计方面，2017年谷歌提出的自动化学习系统（AutoML）试图通过自动创建机器学习系统降低人员成本。$kp$, section = '' where id = 26622;
update t_knowledge_point set title = $kp$人工智能将加速与其他学科领域交叉渗透$kp$, content = $kp$人工智能本身是一门综合性的前沿学科和高度交叉的复合型学科，研究范畴广泛而又异常复杂，其发展需要与计算机科学、数学、认知科学、神经科学和社会科学等学科深度融合。随着超分辨率光学成像、光遗传学调控、透明脑、体细胞克隆等技术的突破，脑与认知科学的发展开启了新时代，能够大规模、更精细地解析智力的神经环路基础和机制，人工智能将进入生物启发的智能阶段，依赖于生物学、脑科学、生命科学和心理学等学科的发现，将机理变为可计算的模型，同时人工智能也会促进脑科学、认知科学、生命科学甚至化学、物理、天文学等传统科学的发展。$kp$, section = '' where id = 26623;
update t_knowledge_point set title = $kp$人工智能产业将蓬勃发展$kp$, content = $kp$随着人工智能技术的进一步成熟以及政府和产业界投入的日益增长，人工智能应用的云端化将不断加速，全球人工智能产业规模在未来10年将进入高速增长期。例如，2016年9月，咨询公司埃森哲发布报告，人工智能技术的应用将为经济发展注入新动力，可在现有基础上将劳动生产率提高40%；到2035年，美、日、英、德、法等12个发达国家的年均经济增长率可以翻一番。2018年麦肯锡公司的研究报告预测，到2030年，约70%的公司将采用至少一种形式的人工智能，人工智能新增经济规模将达到13万亿美元。$kp$, section = '' where id = 26624;
update t_knowledge_point set title = $kp$人工智能将推动人类进入普惠型智能社会$kp$, content = $kp$“人工智能+X”的创新模式将随着技术和产业的发展日趋成熟，对生产力和产业结构产生革命性影响，并推动人类进入普惠型智能社会。2017年国际数据公司IDC在《信息流引领人工智能新时代》白皮书中指出，未来5年人工智能将提升各行业运转效率。我国经济社会转型升级对人工智能有重大需求，在消费场景和行业应用的需求牵引下，需要打破人工智能的感知瓶颈、交互瓶颈和决策瓶颈，促进人工智能技术与社会各行各业的融合提升，建设若干标杆性的应用场景创新，实现低成本、高效益、广范围的普惠型智能社会。$kp$, section = '' where id = 26625;
update t_knowledge_point set title = $kp$人工智能领域的国际竞争将日益激烈$kp$, content = $kp$当前，人工智能领域的国际竞赛已经拉开帷幕，并且将日趋白热化。2018年4月，欧盟委员会计划2018—2020年在人工智能领域投资240亿美元；法国总统在2018年5月宣布《法国人工智能战略》，目的是迎接人工智能发展的新时代，使法国成为人工智能强国；2018年6月，日本《未来投资战略2018》重点推动物联网建设和人工智能的应用。世界军事强国也已逐步形成以加速发展智能化武器装备为核心的竞争态势，例如美国发布的首份《国防战略》报告即谋求通过人工智能等技术创新保持军事优势，确保美国打赢未来战争；俄罗斯2017年提出军工拥抱“智能化”，让导弹和无人机这样的“传统”兵器威力倍增。$kp$, section = '' where id = 26626;
update t_knowledge_point set title = $kp$人工智能的社会学研究将提上议程$kp$, content = $kp$为了确保人工智能的健康可持续发展，使其发展成果造福于民，需要从社会学的角度系统全面地研究人工智能对人类社会的影响，制定完善人工智能法律法规，规避可能的风险。2017年9月，联合国犯罪和司法研究所（UNICRI）决定在海牙成立第一个联合国人工智能和机器人中心，规范人工智能的发展。美国白宫多次组织人工智能领域法律法规问题的研讨会、咨询会。特斯拉等产业巨头牵头成立OpenAI等机构，旨在“以有利于整个人类的方式促进和发展友好的人工智能”。$kp$, section = '' where id = 26627;
update t_knowledge_point set title = $kp$人工智能未来发展的三个趋势$kp$, content = $kp$1）人工智能与物联网结合，给人们生活带来更多方便；
2）自主学习成为人工智能的终极目标；
3）人工智能将对劳动力产生冲击，影响就业。$kp$, section = '' where id = 26900;
update t_knowledge_point set title = $kp$按能力划分的三类人工智能$kp$, content = $kp$人工智能可以分为“弱人工智能”“强人工智能”和“超人工智能”三类。$kp$, section = '' where id = 27120;

do $$
