  if (select count(*) from t_knowledge_point where id in (24394,26404,26468,26619,26620,26621,26622,26623,26624,26625,26626,26627,26900,27120) and not deleted) <> 14 then
    raise exception '清洗条目数异常';
  end if;
end $$;
